// n8n · workflow LANOPS-AGENTE · nodo "Code: robots.txt"
// Modo: Run Once for All Items · JavaScript
// Entrada: respuestas de "HTTP Request: robots.txt", en el mismo orden que "Postgres: empresas".
// Salida: SOLO las empresas cuya url_empleo permite robots.txt (las demás no se visitan).
// Reglas: 200 → se aplican los Disallow/Allow del grupo "LANOPS-bot" o, si no hay, del grupo "*" (gana la regla más larga);
// 4xx (no hay robots.txt) → permitido; 5xx o error de red → NO permitido (lo prudente).
const empresas = $('Postgres: empresas').all().map(i => i.json);
const UA = 'lanops-bot';

function reglas(texto) {
  const grupos = []; let actual = null, leyendoAgentes = false;
  for (const linea of String(texto).split(/\r?\n/)) {
    const l = linea.replace(/#.*/, '').trim(); if (!l) continue;
    const m = l.match(/^([A-Za-z-]+)\s*:\s*(.*)$/); if (!m) continue;
    const k = m[1].toLowerCase(), v = m[2].trim();
    if (k === 'user-agent') {
      if (!leyendoAgentes) { actual = { agentes: [], reglas: [] }; grupos.push(actual); }
      actual.agentes.push(v.toLowerCase()); leyendoAgentes = true;
    } else if (actual && (k === 'disallow' || k === 'allow')) {
      leyendoAgentes = false; if (v) actual.reglas.push({ permitir: k === 'allow', ruta: v });
    } else { leyendoAgentes = false; }
  }
  const propio = grupos.filter(g => g.agentes.some(a => a !== '*' && UA.startsWith(a)));
  const usar = propio.length ? propio : grupos.filter(g => g.agentes.includes('*'));
  return usar.flatMap(g => g.reglas);
}
const casa = (ruta, patron) => {
  const re = '^' + patron.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\\\$$/, '$');
  return new RegExp(re.endsWith('$') ? re : re).test(ruta);
};
function permitido(url, texto) {
  const ruta = (String(url).match(/^https?:\/\/[^/?#]+([^#]*)/) || [])[1] || '/';
  let mejor = null;
  for (const r of reglas(texto)) if (casa(ruta || '/', r.ruta) && (!mejor || r.ruta.length > mejor.ruta.length)) mejor = r;
  return !mejor || mejor.permitir;
}

const salida = [];
$input.all().forEach((item, i) => {
  const e = empresas[i]; if (!e) return;
  const j = item.json, status = Number(j.statusCode || 0);
  let ok;
  if (j.error || !status || status >= 500) ok = false;
  else if (status >= 400) ok = true;
  else ok = permitido(e.url_empleo, j.body ?? j.data ?? '');
  if (ok) salida.push({ json: e });
});
return salida;

// n8n · workflow LANOPS-AGENTE · nodo "Code: texto y petición"
// Modo: Run Once for All Items · JavaScript
// Entrada: respuestas de "HTTP Request: página de empleo", en el mismo orden que "Code: robots.txt".
// HTML → texto (≤ 15.000 caracteres). Si la página trae JSON-LD JobPosting, se le pasa a Claude ese JSON (más fiable).
// Salida: SOLO las empresas con página leída, con la petición a Claude. Las fallidas se cuentan en "Code: leer".
const empresas = $('Code: robots.txt').all().map(i => i.json);
const MODELO = 'claude-sonnet-5-5';
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó',
  uacute: 'ú', ntilde: 'ñ', Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', Ntilde: 'Ñ', uuml: 'ü', ordf: 'ª', ordm: 'º', euro: '€' };
const decod = (s) => s.replace(/&(#x?[0-9a-f]+|\w+);/gi, (m, c) => c[0] === '#'
  ? String.fromCodePoint(parseInt(c[1].toLowerCase() === 'x' ? c.slice(2) : c.slice(1), c[1].toLowerCase() === 'x' ? 16 : 10))
  : (ENT[c] ?? m));
function jsonLd(html) {
  const out = [];
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const walk = (o) => { if (!o || typeof o !== 'object') return;
        if (Array.isArray(o)) return o.forEach(walk);
        const t = [].concat(o['@type'] || []); if (t.includes('JobPosting')) out.push(o);
        if (o['@graph']) walk(o['@graph']); if (o.itemListElement) walk(o.itemListElement); if (o.item) walk(o.item); };
      walk(JSON.parse(m[1].trim()));
    } catch (e) {}
  }
  return out;
}
function texto(html) {
  return decod(html
    .replace(/<(script|style|noscript|svg|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<a\s[^>]*href="([^"#][^"]*)"[^>]*>/gi, ' [enlace: $1] ')
    .replace(/<(br|p|div|li|h[1-6]|tr|section|article)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}
const SYSTEM = `Eres el agente de webs de LANOPS (red de empleo de Gipuzkoa). Recibes la página de empleo de UNA empresa
(texto de la página, con los enlaces marcados como [enlace: …], o datos JSON-LD JobPosting).
Devuelve SOLO un JSON: {"vacantes":[{"puesto":"","ubicacion":"","contrato":"indefinido|temporal|practicas|otro|","jornada":"completa|parcial|","salario_min":0,"descripcion":"","url":""}],"candidatura_espontanea":false,"como_enviar":""}
Reglas:
- Solo ofertas de empleo concretas que la página publica AHORA. No inventes nada; un campo que no está va vacío ("" o 0).
- Ignora menús, noticias, cookies, ofertas cerradas o caducadas y procesos de "bolsa" sin puesto concreto.
- url: el enlace a la ficha de esa oferta si aparece (completo; si es relativo, tal cual); si no, "".
- descripcion: lo que la página diga del puesto (funciones, requisitos), máximo 1500 caracteres.
- Máximo 30 ofertas.
- Si NO hay ninguna oferta concreta pero la página invita a enviar el CV (formulario, correo de RR. HH., "trabaja con nosotros"),
  candidatura_espontanea = true y como_enviar = cómo se envía (correo o formulario), en una frase.`;

const salida = [];
$input.all().forEach((item, i) => {
  const e = empresas[i]; if (!e) return;
  const j = item.json, status = Number(j.statusCode || 0);
  const html = String(j.body ?? j.data ?? '');
  if (j.error || status < 200 || status >= 400 || html.length < 200) return;   // fallo de lectura
  const ld = jsonLd(html);
  const contenido = ld.length
    ? 'JSON-LD JobPosting de la página:\n' + JSON.stringify(ld).slice(0, 15000)
    : 'Texto de la página:\n' + texto(html).slice(0, 15000);
  salida.push({ json: { ...e, fuente_lectura: ld.length ? 'jsonld' : 'html', cuerpo: {
    model: MODELO, max_tokens: 8000, system: SYSTEM,
    messages: [{ role: 'user', content: `Empresa: ${e.nombre} (${e.ciudad || 'Gipuzkoa'})\nURL: ${e.url_empleo}\n\n${contenido}` }]
  } } });
});
return salida;

// n8n · workflow LANOPS-AGENTE · nodo "Code: leer"
// Modo: Run Once for All Items · JavaScript
// Entrada: respuestas de "HTTP Request: Claude", en el mismo orden que "Code: texto y petición".
// Salida: UN item con todas las vacantes leídas y el resultado de cada empresa, para "Postgres: guardar".
// ok = página leída y (≥ 1 oferta o candidatura espontánea). Bloqueada por robots.txt = no cuenta (ni ok ni fallo).
const todas = $('Postgres: empresas').all().map(i => i.json);
const permitidas = new Set($('Code: robots.txt').all().map(i => i.json.empresa));
const leidas = $('Code: texto y petición').all().map(i => i.json);
const txt = (v, n) => String(v ?? '').trim().slice(0, n);
const abs = (u, base) => {
  u = String(u || '').trim(); if (!u) return base;
  if (/^https?:\/\//i.test(u)) return u.slice(0, 255);
  const origen = (base.match(/^https?:\/\/[^/?#]+/) || [''])[0];
  return (u.startsWith('/') ? origen + u : base.replace(/[^/]*$/, '') + u).slice(0, 255);
};

const vacantes = [], lecturas = [], resumen = [];
const porEmpresa = new Map();
$input.all().forEach((item, i) => {
  const e = leidas[i]; if (!e) return;
  try {
    const t = (item.json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
    const r = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
    porEmpresa.set(e.empresa, { e, r });
  } catch (err) { porEmpresa.set(e.empresa, { e, r: null }); }
});

for (const emp of todas) {
  if (!permitidas.has(emp.empresa)) { resumen.push(`${emp.nombre}: bloqueada por robots.txt (no se visita)`); continue; }
  const x = porEmpresa.get(emp.empresa);
  if (!x) { lecturas.push({ empresa: emp.empresa, ok: false }); resumen.push(`${emp.nombre}: no se pudo leer la página`); continue; }
  if (!x.r) { lecturas.push({ empresa: emp.empresa, ok: false }); resumen.push(`${emp.nombre}: respuesta de Claude no válida`); continue; }
  const lista = (Array.isArray(x.r.vacantes) ? x.r.vacantes : []).slice(0, 30)
    .map(v => ({
      empresa: emp.empresa,
      puesto: txt(v.puesto, 150),
      ubicacion: txt(v.ubicacion, 60) || null,
      contrato: ['indefinido', 'temporal', 'practicas', 'otro'].includes(v.contrato) ? v.contrato : null,
      jornada: ['completa', 'parcial'].includes(v.jornada) ? v.jornada : null,
      salario_min: parseInt(v.salario_min, 10) > 0 ? parseInt(v.salario_min, 10) : null,
      requisitos: txt(v.descripcion, 1500) || null,
      url_origen: abs(v.url, emp.url_empleo)
    }))
    .filter(v => v.puesto);
  if (!lista.length && x.r.candidatura_espontanea) {
    lista.push({ empresa: emp.empresa, puesto: 'Candidatura espontánea', ubicacion: emp.ciudad || null, contrato: null,
      jornada: null, salario_min: null, url_origen: emp.url_empleo,
      requisitos: txt(`${emp.nombre} no publica ofertas concretas pero recibe candidaturas. ${x.r.como_enviar || ''}`, 1500) });
  }
  vacantes.push(...lista);
  lecturas.push({ empresa: emp.empresa, ok: lista.length > 0 });
  resumen.push(`${emp.nombre} (${x.e.fuente_lectura}): ${lista.length ? lista.length + ' ofertas' : 'ninguna oferta en el texto (¿ATS con JavaScript?)'}`);
}
return [{ json: { datos: { vacantes, lecturas }, resumen } }];
